-- =============================================================
-- Migrasi `barang` -> `product_information`
--
-- SUMBER DATA: tabel `barang` (barang.sql / database `alangfarma`),
--              3.998 baris, id_barang 2-5176.
--
-- Cakupan: HANYA produk yang namanya tercantum di nama_obat.txt.
--          750 baris `barang` dari 721 nama di nama_obat.txt.
--
-- Pemetaan kolom:
--   id_barang       -> id
--   kd_barang       -> product_id
--   nm_barang       -> product_name
--   hrgjual_barang  -> price
--   sat_barang      -> unit
--   stok_buffer     -> stok_buffer      (kolom BARU, ditambahkan di bawah)
--   manufacturer_id -> dari relasi barang -> supplier (lihat catatan)
--
--   strength        -> DOSIS, diambil dari `nm_barang`
--                      ("Amoxicillin 500 mg Kaplet HJ" -> "500 mg")
--   product_details -> `ket_barang` + `indikasi`, tag HTML dibuang
--
-- CATATAN kolom `strength`:
--   `strength` dipakai aplikasi sebagai DOSIS singkat. Di Products.php
--   nama produk dirender sebagai product_name + "(" + strength + ")",
--   sehingga isi panjang membuat daftar obat tercampur teks indikasi.
--   Karena itu `indikasi` TIDAK dimasukkan ke `strength`, melainkan ke
--   `product_details`. Dosis diambil dari nama barang.
--   Sisanya (alkes, kosmetik, herbal) dikosongkan.
--
-- CATATAN manufacturer_id:
--   Tabel `barang` TIDAK punya kolom supplier. Relasi diturunkan dari
--   riwayat pembelian:
--     barang.id_barang -> trbmasuk_detail.id_barang
--                      -> trbmasuk.kd_trbmasuk -> trbmasuk.id_supplier
--   Bila satu barang pernah dibeli dari beberapa supplier, dipakai
--   supplier pada pembelian TERAKHIR (tgl_trbmasuk terbesar).
--   Tabel `barang_supplier` sengaja TIDAK dipakai (hanya 11 baris).
--
--   713 dari 750 baris mendapat supplier.
--   37 baris belum pernah ada transaksi pembelian -> manufacturer_id = 0.
--
-- PRASYARAT (WAJIB, supaya manufacturer_id merujuk ke baris yang ada):
--   1. install/sql/migrasi_supplier_ke_manufacturer.sql
--   2. install/sql/dedup_manufacturer.sql
--
-- CADANGKAN DULU:
--   mysqldump -u root apotik_alang > backup_sebelum_import_produk.sql
-- =============================================================

SET NAMES utf8mb4;

-- -------------------------------------------------------------
-- 1) Tambah kolom `stok_buffer` (stok minimum) bila belum ada.
-- -------------------------------------------------------------
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME   = 'product_information'
              AND COLUMN_NAME  = 'stok_buffer');
SET @s := IF(@c = 0,
  'ALTER TABLE `product_information`
     ADD COLUMN `stok_buffer` DOUBLE NOT NULL DEFAULT 0 AFTER `unit`',
  'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- -------------------------------------------------------------
-- 2) Lebarkan `product_name`: ada nama sepanjang 53 karakter,
--    sedangkan kolom aslinya varchar(50).
--    `strength` TIDAK diubah (tetap varchar(250)) karena kini hanya
--    berisi dosis singkat.
-- -------------------------------------------------------------
ALTER TABLE `product_information`
  MODIFY `product_name` VARCHAR(255) NOT NULL;

-- -------------------------------------------------------------
-- 3) Isi data. `id` diambil dari `id_barang` agar tetap sinkron
--    dengan referensi data lama.
-- -------------------------------------------------------------
INSERT INTO `product_information`
  (`id`, `product_id`, `product_name`, `price`, `strength`,
   `unit`, `product_details`, `manufacturer_id`, `stok_buffer`,
   `category_id`, `generic_name`, `box_size`, `product_location`, `image`, `status`)
