ON DUPLICATE KEY UPDATE
  `product_id`      = VALUES(`product_id`),
  `product_name`    = VALUES(`product_name`),
  `price`           = VALUES(`price`),
  `strength`        = VALUES(`strength`),
  `unit`            = VALUES(`unit`),
  `product_details` = VALUES(`product_details`),
  `manufacturer_id` = VALUES(`manufacturer_id`),
  `stok_buffer`     = VALUES(`stok_buffer`);

-- -------------------------------------------------------------
-- 4) Samakan manufacturer_id dengan hasil dedup_manufacturer.sql.
--    Supplier 26 & 80 digabung ke 3 & 1 oleh script dedup, sedangkan
--    id di sini diturunkan dari data mentah (pra-dedup). Tanpa langkah
--    ini, 18 baris akan menunjuk manufacturer yang sudah dihapus.
-- -------------------------------------------------------------
UPDATE `product_information` p
  JOIN `manufacturer_information` k ON k.`manufacturer_id` = 1
   SET p.`manufacturer_id` = 1
 WHERE p.`manufacturer_id` = 80
   AND NOT EXISTS (SELECT 1 FROM `manufacturer_information` x
                    WHERE x.`manufacturer_id` = 80);

UPDATE `product_information` p
  JOIN `manufacturer_information` k ON k.`manufacturer_id` = 3
   SET p.`manufacturer_id` = 3
 WHERE p.`manufacturer_id` = 26
   AND NOT EXISTS (SELECT 1 FROM `manufacturer_information` x
                    WHERE x.`manufacturer_id` = 26);
